let preparedPromise;

async function readCompressedSource() {
  const bytes = Uint8Array.from(atob(compressedSourceBase64), character => character.charCodeAt(0));
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
  return JSON.parse(await new Response(stream).text());
}

export function loadAustraliaPreparedOfficial() {
  preparedPromise ??= readCompressedSource().then(source => Object.freeze(importAustralianAnnualSource(source)));
  return preparedPromise;
}
